from pathlib import Path
from hashlib import sha256
import importlib.util, tempfile, json, sys, io, contextlib
from unittest.mock import patch
skill=Path('.agents/skills/joso-jdrt-runner/scripts').resolve()
sys.path.insert(0,str(skill))
spec=importlib.util.spec_from_file_location('review_sync',skill/'choice_sync_status.py')
sync=importlib.util.module_from_spec(spec);spec.loader.exec_module(sync)
results=[]
def setup(root):
    out=root/'06_研究結果/jdrt/goal_20261017';out.mkdir(parents=True)
    ws=root/'ws';(ws/'driver_logs').mkdir(parents=True)
    impl=root/'impl.py';impl.write_bytes(b'# fixed implementation\n')
    marker='<!-- choice_record:accepted -->'
    task='05_タスク管理/jdrt/JDRT-受付代替行動_詳細タスク.md'
    docs=sync.DISPLAY_FILES+[task,'fifth.md']
    for name in docs:
        p=root/name;p.parent.mkdir(parents=True,exist_ok=True)
        text=('OLD summary\r\n| CH-M1 | monitor | definition | OLD display |\r\n' if name==task else 'OLD summary\r\n')+marker+'\r\n'
        if name=='context.md':text+='<!-- AGENT_CURRENT_END -->\r\n'
        p.write_bytes(text.encode())
    cfg={'protocol':'synthetic_choice','workspace':'ws','cells':[{'cell_id':'a'},{'cell_id':'b'}],
         'record_files':docs+['ledger.jsonl'],'execution':{'implementation_files':['impl.py']}}
    p=root/'04_プログラム/config/jdrt_realtime_choice_v1.json';p.parent.mkdir(parents=True);p.write_text(json.dumps(cfg),encoding='utf-8')
    for run,cell in [('accepted','a'),('current','b')]:
        folder=ws/'runs'/run;folder.mkdir(parents=True)
        m={'run_id':run,'cell_id':cell,'purpose':'core','status':'COMPLETED','pid':999999,'end_sec':21600}
        (folder/'manifest.json').write_text(json.dumps(m),encoding='utf-8')
    proof=root/'proof.json';proof.write_text(json.dumps({'status':'PASS','core_adoption_permitted':True}),encoding='utf-8')
    row={'run_id':'accepted','cell_id':'a','protocol':cfg['protocol'],'purpose':'core','validation_status':'PASS',
         'manifest_sha256':sync.file_sha(ws/'runs/accepted/manifest.json'),'implementation_sha256':{'impl.py':sync.file_sha(impl)},
         'validation_report':'proof.json','validation_report_sha256':sync.file_sha(proof)}
    (root/'ledger.jsonl').write_text(json.dumps(row)+'\n',encoding='utf-8')
    cp=out/'G4実装・実SUMO_継続チェックポイント.json';cp.write_text(json.dumps({'summary':'OLD summary','goal_status':'ACTIVE'}),encoding='utf-8')
    return out,ws,docs,cp,marker
def call(root,out,apply=True):
    with patch.object(sync,'ROOT',root),patch.object(sync,'OUT',out),patch.object(sync,'pid_alive',lambda _:False),patch.object(sys,'argv',['sync']+(['--apply'] if apply else [])),contextlib.redirect_stdout(io.StringIO()):
        sync.main()
with tempfile.TemporaryDirectory(prefix='choice_forward_review_') as temp:
    root=Path(temp)/'normal';root.mkdir();out,ws,docs,cp,marker=setup(root)
    call(root,out)
    first={name:(root/name).read_bytes() for name in docs}
    check=json.loads(cp.read_text(encoding='utf-8'))
    assert check['running']==[] and check['unrecorded_runs']==['current'] and check['observed_formally_recorded']==1
    assert 'COMPLETED' in check['summary'] and '正式記録1/2' in check['summary']
    call(root,out)
    second={name:(root/name).read_bytes() for name in docs}
    assert first==second
    assert all(raw.decode().count(marker)==1 for raw in second.values())
    assert (root/docs[3]).read_text(encoding='utf-8').count('| CH-M1 |')==1
    assert not (ws/'driver_logs/writer.lock').exists()
    results.append({'case':'normal_CRLF_repeated_apply_COMPLETED','status':'PASS','markers_preserved':True,'no_duplicate_row_or_summary':True,'completed_not_running':True})
    for case in ['writer_lock','recovery_lock','pending_record','partial_marker','accepted_SHA_mismatch']:
        root=Path(temp)/case;root.mkdir();out,ws,docs,cp,marker=setup(root)
        if case=='writer_lock':(ws/'driver_logs/writer.lock').write_text('existing owner')
        if case=='recovery_lock':(ws/'driver_logs/recovery.lock').write_text('existing recovery')
        if case=='pending_record':
            p=ws/'record_transactions/t/journal.json';p.parent.mkdir(parents=True);p.write_text(json.dumps({'status':'PREPARED','run_id':'current'}))
        if case=='partial_marker':(root/'fifth.md').write_text('missing marker')
        if case=='accepted_SHA_mismatch':(root/'impl.py').write_text('# changed implementation')
        before={p:p.read_bytes() for p in [*[root/name for name in docs],cp]}
        try:call(root,out)
        except (RuntimeError,FileExistsError) as error:
            assert all(p.read_bytes()==raw for p,raw in before.items())
            results.append({'case':case,'status':'PASS','blocked':type(error).__name__,'message':str(error),'target_bytes_unchanged':True})
        else:raise AssertionError('Did not reject '+case)
    root=Path(temp)/'partial_write';root.mkdir();out,ws,docs,cp,marker=setup(root)
    target=root/docs[1];before={p:p.read_bytes() for p in [*[root/name for name in docs],cp]}
    original_write=Path.write_text;injected=[False]
    def broken_write(path,data,*a,**kw):
        if path==target and not injected[0]:
            injected[0]=True;path.write_bytes(b'PARTIAL');raise OSError('synthetic disk failure after truncation')
        return original_write(path,data,*a,**kw)
    try:
        with patch.object(Path,'write_text',broken_write):call(root,out)
    except OSError:pass
    else:raise AssertionError('injected failure was not raised')
    damaged=[p.relative_to(root).as_posix() for p,raw in before.items() if p.read_bytes()!=raw]
    assert damaged==[]
    assert all(p.read_bytes()==raw for p,raw in before.items())
    assert not (ws/'driver_logs/writer.lock').exists()
    results.append({'case':'partial_write_rollback','status':'PASS','damaged_targets':damaged,'failing_target_marker_preserved':marker in target.read_text(),'all_original_bytes_restored':True,'writer_lock_released':True})
    root=Path(temp)/'checkpoint_failure';root.mkdir();out,ws,docs,cp,marker=setup(root)
    before={p:p.read_bytes() for p in [*[root/name for name in docs],cp]}
    real_save=sync.save_json
    def saved_then_failed(path,value):
        real_save(path,value)
        raise OSError('synthetic failure after checkpoint replacement')
    try:
        with patch.object(sync,'save_json',saved_then_failed):call(root,out)
    except OSError:pass
    else:raise AssertionError('checkpoint failure was not raised')
    assert all(p.read_bytes()==raw for p,raw in before.items())
    assert not (ws/'driver_logs/writer.lock').exists()
    results.append({'case':'checkpoint_postreplacement_failure','status':'PASS','all_original_bytes_restored':True,'writer_lock_released':True})
print(json.dumps({'status':'PASS_AFTER_MINIMAL_FIX','cases':results},ensure_ascii=True))
